# ----------------------------------------------------------------------
# 2️⃣ ROOT DISCOVERY
# ----------------------------------------------------------------------
def find_content_root() -> pathlib.Path:
    """Return the absolute Path that contains the markdown vault."""
    if ENV_CONTENT_ROOT:
        p = pathlib.Path(ENV_CONTENT_ROOT)
        print(f"[ROOT] Using ENV FEATURED_CONTENT_ROOT = {p}")
        return p

    candidates: List[pathlib.Path] = []
    ws = os.getenv("GITHUB_WORKSPACE")
    if ws:
        candidates.append(pathlib.Path(ws))
    here = pathlib.Path(__file__).resolve()
    candidates.extend(here.parents)
    candidates.append(pathlib.Path.cwd())

    for base in candidates:
        p = base / CONTENT_DIRNAME
        if p.is_dir():
            print(f"[ROOT] Discovered content root: {p}")
            return p

    fallback = here.parent / CONTENT_DIRNAME
    print(f"[ROOT] Fallback content root: {fallback}")
    return fallback


# ----------------------------------------------------------------------
# 3️⃣ MARKDOWN DISCOVERY
# ----------------------------------------------------------------------
def iter_markdown(root: pathlib.Path):
    """Yield every *.md file under *root*, skipping the black‑list."""
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in EXCLUDE_DIRS]
        for fname in filenames:
            if fname.lower().endswith(".md"):
                yield pathlib.Path(dirpath) / fname


# ----------------------------------------------------------------------
# 4️⃣ FRONT‑MATTER HELPERS
# ----------------------------------------------------------------------
FM_RE = re.compile(r"^---\r?\n(.*?)(?:\r?\n)---\r?\n?", re.S)


def try_load_yaml(text: str) -> Optional[Dict[str, Any]]:
    try:
        import yaml  # type: ignore
    except Exception:
        return None
    try:
        data = yaml.safe_load(text)
        return data if isinstance(data, dict) else None
    except Exception:
        return None


def fallback_parse_yaml(text: str) -> Optional[Dict[str, Any]]:
    """Very tolerant YAML‑ish parser – sufficient for our simple front‑matter."""
    lines = text.splitlines()
    norm = [re.sub(r"^\t+", lambda m: "  " * len(m.group(0)), ln) for ln in lines]
    i = 0

    def cast_scalar(s: str) -> Any:
        s = s.strip()
        if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
            s = s[1:-1]
        if s.lower() == "true":
            return True
        if s.lower() == "false":
            return False
        if s.startswith("[") and s.endswith("]"):
            inner = s[1:-1].strip()
            if not inner:
                return []
            return [cast_scalar(p) for p in inner.split(",")]
        try:
            if "." in s:
                return float(s)
            return int(s)
        except Exception:
            return s

    def parse_block(indent: int) -> Any:
        nonlocal i
        mode = None
        obj: Dict[str, Any] = {}
        arr: List[Any] = []

        while i < len(norm):
            line = norm[i]
            if not line.strip():
                i += 1
                continue
            cur_indent = len(line) - len(line.lstrip(" "))
            if cur_indent < indent:
                break
            if cur_indent > indent:
                if mode == "list" and arr:
                    arr[-1] = parse_block(cur_indent)
                elif mode == "dict" and obj:
                    last_key = list(obj.keys())[-1]
                    obj[last_key] = parse_block(cur_indent)
                else:
                    break
                continue
            content = line[indent:]
            if content.startswith("- "):
                mode = "list"
                val = content[2:].strip()
                arr.append(cast_scalar(val) if val else {})
                i += 1
            else:
                if ":" in content:
                    mode = "dict"
                    k, v = content.split(":", 1)
                    obj[k.strip()] = cast_scalar(v) if v.strip() else {}
                    i += 1
                else:
                    break
        return arr if mode == "list" else obj

    root: Dict[str, Any] = {}
    while i < len(norm):
        line = norm[i]
        if not line.strip():
            i += 1
            continue
        if ":" in line:
            k, v = line.split(":", 1)
            key, val = k.strip(), v.strip()
            i += 1
            if val == "":
                indent = len(line) - len(line.lstrip(" ")) + 2
                root[key] = parse_block(indent)
            else:
                root[key] = cast_scalar(val)
        else:
            i += 1
    return root if root else None


def read_front_matter(md_path: pathlib.Path) -> Tuple[Optional[Dict[str, Any]], str, str]:
    """Return (front‑matter dict or None, body text, loader used)."""
    text = md_path.read_text(encoding="utf-8", errors="ignore")
    m = FM_RE.match(text)
    body = text[m.end():] if m else text
    fm_raw = m.group(1) if m else ""
    data = try_load_yaml(fm_raw)
    used = "pyyaml" if data is not None else "fallback"
    if data is None and fm_raw:
        data = fallback_parse_yaml(fm_raw)
    return (data if isinstance(data, dict) else None), body, used


# ----------------------------------------------------------------------
# 5️⃣ %%‑SECTION HELPERS
# ----------------------------------------------------------------------
def split_definitions_section(md_text: str) -> Tuple[str, Dict[str, str]]:
    """
    Everything after the first `%%` line is interpreted as a simple
    `key: value` map.
    Returns (body_without_definitions, {key: value, …})
    """
    parts = md_text.split("%%")
    if len(parts) < 2:
        return md_text, {}
    defs_raw = parts[1]
    body = parts[0]
    defs: Dict[str, str] = {}
    for line in defs_raw.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if ":" not in line:
            continue
        key, val = line.split(":", 1)
        defs[key.strip()] = val.strip()
    return body, defs


# ----------------------------------------------------------------------
# 6️⃣ PAGE‑LEVEL EXTRACTION
# ----------------------------------------------------------------------
def resolve_featured_entry(raw_entry: Any, definitions: Dict[str, str]) -> Any:
    """Resolve a scalar or list entry against the definitions map."""
    if isinstance(raw_entry, list):
        return [resolve_featured_entry(e, definitions) for e in raw_entry]

    if isinstance(raw_entry, str):
        return definitions.get(raw_entry, raw_entry)

    return raw_entry


def extract_featured_from_page(md_path: pathlib.Path,
                              root: pathlib.Path) -> Optional[Dict[str, Any]]:
    """
    Return a dict with the extracted data for a page that contains
    `featured_data` in its front‑matter, or None if the key is missing.
    The dict always contains the keys:
        - src_rel
        - title
        - featured_desc
        - featured_image
        - fun_facts (list)
    """
    fm, body, _ = read_front_matter(md_path)
    if not fm or "featured_data" not in fm:
        return None

    featured_raw = fm["featured_data"]
    if not isinstance(featured_raw, dict):
        return None

    # Resolve definitions from the %% block
    _, definitions = split_definitions_section(body)

    desc_key = featured_raw.get("featured_desc")
    img_key  = featured_raw.get("featured_image")
    facts_raw = featured_raw.get("fun_facts", [])

    resolved_desc   = resolve_featured_entry(desc_key, definitions)
    resolved_img    = resolve_featured_entry(img_key, definitions)
    resolved_facts  = resolve_featured_entry(facts_raw, definitions)

    # Normalise fun_facts to a list of strings
    if isinstance(resolved_facts, list):
        fun_facts = [str(f) for f in resolved_facts]
    else:
        fun_facts = [str(resolved_facts)]

    # Title for the JSON report (front‑matter title if present, else filename)
    title = fm.get("title")
    if isinstance(title, str) and title.strip():
        title = title.strip()
    else:
        title = md_path.stem

    rel_path = md_path.relative_to(root).as_posix()

    return {
        "src_rel": rel_path,
        "title": title,
        "featured_desc": resolved_desc,
        "featured_image": resolved_img,
        "fun_facts": fun_facts,
    }


