def write_json_report(derived_dir: pathlib.Path,
                      data: List[Dict[str, Any]],
                      warnings: List[str]) -> None:
    """Write the JSON report and a markdown warnings file."""
    derived_dir.mkdir(parents=True, exist_ok=True)

    report_path = derived_dir / EXTRACTED_JSON
    warn_path   = derived_dir / WARNINGS_MD

    report = {
        "meta": {
            "total_pages_scanned": len(data),
            "featured_pages_found": len(data),
            "warnings": len(warnings),
        },
        "featured_pages": data,
    }

    if DRY_RUN:
        print("[DRY] Would write JSON report to:", report_path)
    else:
        report_path.write_text(
            json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8"
        )
        print("[WROTE] JSON report ->", report_path)

    warning_lines = ["# Featured Block Generator Warnings", ""]
    if warnings:
        warning_lines.append("## Issues detected")
        warning_lines.extend(warnings)
    else:
        warning_lines.append("_No warnings_")
    warning_text = "\n".join(warning_lines)

    if DRY_RUN:
        print("[DRY] Would write warnings to:", warn_path)
    else:
        warn_path.write_text(warning_text, encoding="utf-8")
        print("[WROTE] Warnings ->", warn_path)


# ----------------------------------------------------------------------
# 8️⃣ REPLACE FIRST CALL‑OUT ON _index.md
# ----------------------------------------------------------------------
CALL_OUT_START_RE = re.compile(r"^> \[!")


def replace_first_callout(lines: List[str],
                         new_block: List[str]) -> Tuple[List[str], bool]:
    """
    Replace only the *first* call‑out block (the one that starts with `> [!`).
    Returns the new list of lines and a flag indicating whether a change was made.
    """
    start = None
    end   = None

    for i, ln in enumerate(lines):
        if CALL_OUT_START_RE.match(ln):
            start = i
            j = i + 1
            while j < len(lines):
                cur = lines[j]
                if cur.strip() == "":
                    j += 1
                    continue
                if CALL_OUT_START_RE.match(cur):
                    break          # another call‑out → stop
                if cur.startswith(">"):
                    j += 1
                    continue
                break                # non‑`>` line → end of block
            end = j
            break                     # only the first call‑out is replaced

    if start is None:
        return lines, False          # no call‑out found

    old_block = lines[start:end]
    if old_block == new_block:      # already up‑to‑date
        return lines, False

    new_lines = lines[:start] + new_block + lines[end:]
    return new_lines, True


# ----------------------------------------------------------------------
# 9️⃣ RENDER CALL‑OUT BLOCK
# ----------------------------------------------------------------------
def render_featured_block(featured: Dict[str, Any],
                         facts: List[str],
                         max_facts: int = MAX_FUN_FACTS) -> List[str]:
    """
    Build the markdown lines for the call‑out.
    * `featured` contains the description and the optional image.
    * `facts` is the *already shuffled* list of all fun‑facts from the vault.
    """
    # Description – we know the chosen page is guaranteed to have one.
    desc = str(featured.get("featured_desc", ""))

    # Image – optional.  If missing/None/empty we simply omit the line.
    raw_img = featured.get("featured_image")
    img = str(raw_img).strip() if isinstance(raw_img, str) else ""
    # If the resolved value is something other than a string (e.g. None),
    # treat it as missing.
    if not img:
        img = ""  # ensure we have a plain empty string

    chosen_facts = facts[:max_facts]

    out: List[str] = [
        "> [!tip] Featured Article & Fun Facts",
        "> > [!note] Featured Article",
        "> > ",
        f"> > {desc}",
    ]

    # Only add the image line when we actually have an image value.
    if img:
        out.append(f"> > {img}")

    out.extend([
        ">",                                   # blank line between sections
        "> > [!info] Did you know...",
    ])

    for f in chosen_facts:
        out.append(f"> > - {f}")

    out.append("")   # final blank line
    return out


# ----------------------------------------------------------------------
# 10️⃣ MAIN DRIVER
# ----------------------------------------------------------------------
def main() -> None:
    root = find_content_root()
    all_pages: List[Dict[str, Any]] = []   # every page that has featured_data
    warnings: List[str] = []

    # --------------------------------------------------------------
    # Scan the vault and collect data
    # --------------------------------------------------------------
    md_files = list(iter_markdown(root))
    print(f"[SCAN] Found {len(md_files)} markdown files under {root}")

    for md in md_files:
        try:
            entry = extract_featured_from_page(md, root)
            if entry:
                all_pages.append(entry)
        except Exception as exc:
            rel = md.relative_to(root).as_posix()
            warnings.append(f"- Error processing {rel}: {exc}")

    # --------------------------------------------------------------
    # Write JSON report & warnings (inside content/Meta/...)
    # --------------------------------------------------------------
    derived_dir_abs = root / DERIVED_DIR_REL
    write_json_report(derived_dir_abs, all_pages, warnings)

    if not all_pages:
        print("[INFO] No pages with `featured_data` – nothing to update.")
        return

    # --------------------------------------------------------------
    # Build the GLOBAL fun‑fact pool (includes every page)
    # --------------------------------------------------------------
    global_facts: List[str] = []
    for p in all_pages:
        global_facts.extend(p.get("fun_facts", []))

    random.shuffle(global_facts)

    # --------------------------------------------------------------
    # FILTER pages that are eligible to be the *featured article*.
    # They must have a non‑empty description.
    # --------------------------------------------------------------
    eligible = [
        p for p in all_pages
        if isinstance(p.get("featured_desc"), str) and p["featured_desc"].strip()
    ]

    if not eligible:
        warnings.append(
            "- No page with a valid `featured_desc` found. "
            "Cannot render a featured article."
        )
        print("[WARN] No eligible featured article – skipping home‑page update.")
    else:
        # --------------------------------------------------------------
        # Choose ONE page at random from the eligible set
        # --------------------------------------------------------------
        featured_entry = random.choice(eligible)

        # --------------------------------------------------------------
        # Load the home page and replace its first call‑out
        # --------------------------------------------------------------
        home_path = root / "_index.md"
        if not home_path.is_file():
            warnings.append("- Home page `_index.md` not found.")
            print("[WARN] Home page not found – aborting.")
        else:
            raw_home = home_path.read_text(encoding="utf-8")
            home_lines = raw_home.splitlines()

            new_block = render_featured_block(
                featured=featured_entry,
                facts=global_facts,
                max_facts=MAX_FUN_FACTS,
            )

            new_home_lines, changed = replace_first_callout(home_lines, new_block)

            if not changed:
                print("[SKIP] Call‑out on home page already up‑to‑date.")
            else:
                new_home_text = "\n".join(new_home_lines).rstrip() + "\n"
                if DRY_RUN:
                    print("[DRY] Would write updated home page.")
                else:
                    home_path.write_text(new_home_text, encoding="utf-8")
                    print("[WROTE] Updated home page ->", home_path)

    # --------------------------------------------------------------
    # Final summary
    # --------------------------------------------------------------
    print("\n=== Summary ===")
    print(f"Pages with featured_data : {len(all_pages)}")
    print(f"Eligible featured pages   : {len(eligible)}")
    print(f"Warnings generated        : {len(warnings)}")
    if warnings:
        print("\nWarnings:")
        for w in warnings:
            print(w)


if __name__ == "__main__":
    main()
